import sys

def main():
    data = sys.stdin.read().split()
    n, head = int(data[0]), int(data[1])
    manager = [int(x) for x in data[2:2 + n]]
    inform = [int(x) for x in data[2 + n:2 + 2 * n]]
    children = [[] for _ in range(n)]
    for i in range(n):
        if manager[i] >= 0:
            children[manager[i]].append(i)
    best = 0
    stack = [(head, 0)]
    while stack:
        u, t = stack.pop()
        if t > best:
            best = t
        for v in children[u]:
            stack.append((v, t + inform[u]))
    print(best)

